<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/database/setup.php';initializeRESposDatabase();require_once __DIR__.'/includes/functions.php';$db=getDBConnection();$config=getAppConfig();$currency=$_GET['moneda']??$config['moneda_principal'];if(!array_key_exists($currency,availableCurrencies()))$currency='CUP';$cats=$db->query('SELECT * FROM categorias WHERE activa=1 ORDER BY orden,nombre')->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($config['nombre_restaurante'])?> · Carta</title><link rel="stylesheet" href="<?=url('assets/css/style.css')?>"></head><body><div class="public-menu"><header class="public-head"><img src="<?=publicAsset($config['logo_path']??null)?>"><h1 class="gold"><?=h($config['nombre_restaurante'])?></h1><p class="muted"><?=h($config['direccion'])?> · <?=h($config['telefonos'])?></p><?php if($config['redes_sociales']):?><p class="muted"><?=h($config['redes_sociales'])?></p><?php endif;?><form><label style="display:inline-block">Moneda <select name="moneda" onchange="this.form.submit()" style="width:auto"><option>CUP</option><option>USD</option><option>EUR</option><option>JPY</option><option>MXN</option></select></label></form></header><?php foreach($cats as $cat):$s=$db->prepare('SELECT * FROM platos WHERE categoria_id=? AND activo=1 ORDER BY nombre');$s->execute([$cat['id']]);$items=$s->fetchAll();if(!$items)continue;?><section><h2 class="gold" style="border-bottom:1px solid var(--gold);padding-bottom:8px"><?=h($cat['nombre'])?></h2><div class="menu-grid"><?php foreach($items as $p):$price=fromCUP((float)$p['precio_cup'],$currency,$config);?><article class="card dish"><img src="<?=publicAsset($p['foto_path'])?>"><div class="dish-body"><h3><?=h($p['nombre'])?></h3><p class="muted"><?=h($p['descripcion'])?></p><?php if($p['ingredientes']):?><p class="muted"><b>Ingredientes:</b> <?=h($p['ingredientes'])?></p><?php endif;?><?php if($p['guarniciones']):?><p class="muted"><b>Guarnición:</b> <?=h($p['guarniciones'])?></p><?php endif;?><div class="price"><?=money($price,$currency)?></div></div></article><?php endforeach;?></div></section><?php endforeach;?></div></body></html>
